import{_ as a,H as t,f as s,i}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"07丨什么是SQL函数？为什么使用SQL函数可能会带来问题？","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是SQL函数","slug":"什么是sql函数","link":"#什么是sql函数","children":[]},{"level":2,"title":"常用的SQL函数有哪些","slug":"常用的sql函数有哪些","link":"#常用的sql函数有哪些","children":[{"level":3,"title":"算术函数","slug":"算术函数","link":"#算术函数","children":[]},{"level":3,"title":"字符串函数","slug":"字符串函数","link":"#字符串函数","children":[]},{"level":3,"title":"日期函数","slug":"日期函数","link":"#日期函数","children":[]},{"level":3,"title":"转换函数","slug":"转换函数","link":"#转换函数","children":[]}]},{"level":2,"title":"用SQL函数对王者荣耀英雄数据做处理","slug":"用sql函数对王者荣耀英雄数据做处理","link":"#用sql函数对王者荣耀英雄数据做处理","children":[]},{"level":2,"title":"为什么使用SQL函数会带来问题","slug":"为什么使用sql函数会带来问题","link":"#为什么使用sql函数会带来问题","children":[]},{"level":2,"title":"关于大小写的规范","slug":"关于大小写的规范","link":"#关于大小写的规范","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"SQL必知必会/07丨什么是SQL函数？为什么使用SQL函数可能会带来问题？.md","filePath":"SQL必知必会/07丨什么是SQL函数？为什么使用SQL函数可能会带来问题？.md","lastUpdated":1779816304000}'),n={name:"SQL必知必会/07丨什么是SQL函数？为什么使用SQL函数可能会带来问题？.md"};function p(o,e,l,c,d,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="_07丨什么是sql函数-为什么使用sql函数可能会带来问题" tabindex="-1">07丨什么是SQL函数？为什么使用SQL函数可能会带来问题？ <a class="header-anchor" href="#_07丨什么是sql函数-为什么使用sql函数可能会带来问题" aria-label="Permalink to &quot;07丨什么是SQL函数？为什么使用SQL函数可能会带来问题？&quot;">​</a></h1><p>函数在计算机语言的使用中贯穿始终，在SQL中我们也可以使用函数对检索出来的数据进行函数操作，比如求某列数据的平均值，或者求字符串的长度等。从函数定义的角度出发，我们可以将函数分成内置函数和自定义函数。在SQL语言中，同样也包括了内置函数和自定义函数。内置函数是系统内置的通用函数，而自定义函数是我们根据自己的需要编写的，下面讲解的是SQL的内置函数。</p><p>你需要从以下几个方面掌握SQL函数：</p><ol><li>什么是SQL函数？</li><li>内置的SQL函数都包括哪些？</li><li>如何使用SQL函数对一个数据表进行操作，比如针对一个王者荣耀的英雄数据库，我们可以使用这些函数完成哪些操作？</li><li>什么情况下使用SQL函数？为什么使用SQL函数有时候会带来问题？</li></ol><h2 id="什么是sql函数" tabindex="-1">什么是SQL函数 <a class="header-anchor" href="#什么是sql函数" aria-label="Permalink to &quot;什么是SQL函数&quot;">​</a></h2><p>当我们学习编程语言的时候，也会遇到函数。函数的作用是什么呢？它可以把我们经常使用的代码封装起来，需要的时候直接调用即可。这样既提高了代码效率，又提高了可维护性。</p><p>SQL中的函数一般是在数据上执行的，可以很方便地转换和处理数据。一般来说，当我们从数据表中检索出数据之后，就可以进一步对这些数据进行操作，得到更有意义的结果，比如返回指定条件的函数，或者求某个字段的平均值等。</p><h2 id="常用的sql函数有哪些" tabindex="-1">常用的SQL函数有哪些 <a class="header-anchor" href="#常用的sql函数有哪些" aria-label="Permalink to &quot;常用的SQL函数有哪些&quot;">​</a></h2><p>SQL提供了一些常用的内置函数，当然你也可以自己定义SQL函数。SQL的内置函数对于不同的数据库软件来说具有一定的通用性，我们可以把内置函数分成四类：</p><ol><li>算术函数</li><li>字符串函数</li><li>日期函数</li><li>转换函数</li></ol><p>这4类函数分别代表了算术处理、字符串处理、日期处理、数据类型转换，它们是SQL函数常用的划分形式，你可以思考下，为什么是这4个维度？</p><p>函数是对提取出来的数据进行操作，那么数据表中字段类型的定义有哪几种呢？</p><p>我们经常会保存一些数值，不论是整数类型，还是浮点类型，实际上对应的就是数值类型。同样我们也会保存一些文本内容，可能是人名，也可能是某个说明，对应的就是字符串类型。此外我们还需要保存时间，也就是日期类型。那么针对数值、字符串和日期类型的数据，我们可以对它们分别进行算术函数、字符串函数以及日期函数的操作。如果想要完成不同类型数据之间的转换，就可以使用转换函数。</p><h3 id="算术函数" tabindex="-1">算术函数 <a class="header-anchor" href="#算术函数" aria-label="Permalink to &quot;算术函数&quot;">​</a></h3><p>算术函数，顾名思义就是对数值类型的字段进行算术运算。常用的算术函数及含义如下表所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/193b171970c90394576d3812a46dd8e1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/193b171970c90394576d3812a46dd8e1.png" alt=""></a></p><p>这里我举一些简单的例子，你来体会下：</p><p><code>SELECT ABS(-2)</code>，运行结果为2。</p><p><code>SELECT MOD(101,3)</code>，运行结果2。</p><p><code>SELECT ROUND(37.25,1)</code>，运行结果37.3。</p><h3 id="字符串函数" tabindex="-1">字符串函数 <a class="header-anchor" href="#字符串函数" aria-label="Permalink to &quot;字符串函数&quot;">​</a></h3><p>常用的字符串函数操作包括了字符串拼接，大小写转换，求长度以及字符串替换和截取等。具体的函数名称及含义如下表所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/c161033ebeeaa8eb2436742f0f818a4d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/c161033ebeeaa8eb2436742f0f818a4d.png" alt=""></a></p><p>这里同样有一些简单的例子，你可以自己运行下：</p><p><code>SELECT CONCAT(&#39;abc&#39;, 123)</code>，运行结果为abc123。</p><p><code>SELECT LENGTH(&#39;你好&#39;)</code>，运行结果为6。</p><p><code>SELECT CHAR_LENGTH(&#39;你好&#39;)</code>，运行结果为2。</p><p><code>SELECT LOWER(&#39;ABC&#39;)</code>，运行结果为abc。</p><p><code>SELECT UPPER(&#39;abc&#39;)</code>，运行结果ABC。</p><p><code>SELECT REPLACE(&#39;fabcd&#39;, &#39;abc&#39;, 123)</code>，运行结果为f123d。</p><p><code>SELECT SUBSTRING(&#39;fabcd&#39;, 1,3)</code>，运行结果为fab。</p><h3 id="日期函数" tabindex="-1">日期函数 <a class="header-anchor" href="#日期函数" aria-label="Permalink to &quot;日期函数&quot;">​</a></h3><p>日期函数是对数据表中的日期进行处理，常用的函数包括：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/3dec8d799b1363d38df34ed3fdd29045.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/3dec8d799b1363d38df34ed3fdd29045.png" alt=""></a></p><p>下面是一些简单的例子，你可自己运行下：</p><p><code>SELECT CURRENT_DATE()</code>，运行结果为2019-04-03。</p><p><code>SELECT CURRENT_TIME()</code>，运行结果为21:26:34。</p><p><code>SELECT CURRENT_TIMESTAMP()</code>，运行结果为2019-04-03 21:26:34。</p><p><code>SELECT EXTRACT(YEAR FROM &#39;2019-04-03&#39;)</code>，运行结果为2019。</p><p><code>SELECT DATE(&#39;2019-04-01 12:00:05&#39;)</code>，运行结果为2019-04-01。</p><p>这里需要注意的是，DATE日期格式必须是yyyy-mm-dd的形式。如果要进行日期比较，就要使用DATE函数，不要直接使用日期与字符串进行比较，我会在后面的例子中讲具体的原因。</p><h3 id="转换函数" tabindex="-1">转换函数 <a class="header-anchor" href="#转换函数" aria-label="Permalink to &quot;转换函数&quot;">​</a></h3><p>转换函数可以转换数据之间的类型，常用的函数如下表所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/5d977d747ed1fddca3acaab33d29f459.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/5d977d747ed1fddca3acaab33d29f459.png" alt=""></a></p><p>这两个函数不像其他函数，看一眼函数名就知道代表什么、如何使用。下面举了这两个函数的例子，你需要自己运行下：</p><p><code>SELECT CAST(123.123 AS INT)</code>，运行结果会报错。</p><p><code>SELECT CAST(123.123 AS DECIMAL(8,2))</code>，运行结果为123.12。</p><p><code>SELECT COALESCE(null,1,2)</code>，运行结果为1。</p><p>CAST函数在转换数据类型的时候，不会四舍五入，如果原数值有小数，那么转换为整数类型的时候就会报错。不过你可以指定转化的小数类型，在MySQL和SQL Server中，你可以用 <code>DECIMAL(a,b)</code> 来指定，其中a代表整数部分和小数部分加起来最大的位数，b代表小数位数，比如 <code>DECIMAL(8,2)</code> 代表的是精度为8位（整数加小数位数最多为8位），小数位数为2位的数据类型。所以 <code>SELECT CAST(123.123 AS DECIMAL(8,2))</code> 的转换结果为123.12。</p><h2 id="用sql函数对王者荣耀英雄数据做处理" tabindex="-1">用SQL函数对王者荣耀英雄数据做处理 <a class="header-anchor" href="#用sql函数对王者荣耀英雄数据做处理" aria-label="Permalink to &quot;用SQL函数对王者荣耀英雄数据做处理&quot;">​</a></h2><p>我创建了一个王者荣耀英雄数据库，一共有69个英雄，23个属性值。SQL文件见Github地址： <a href="https://github.com/cystanford/sql_heros_data" target="_blank" rel="noreferrer">https://github.com/cystanford/sql_heros_data</a>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/7b14aeedd80fd7e8fb8074f9884d6b24.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/7b14aeedd80fd7e8fb8074f9884d6b24.png" alt=""></a></p><p>我们现在把这个文件导入到MySQL中，你可以使用Navicat可视化数据库管理工具将.sql文件导入到数据库中。数据表为heros，然后使用今天学习的SQL函数，对这个英雄数据表进行处理。</p><p>首先显示英雄以及他的物攻成长，对应字段为 <code>attack_growth</code>。我们让这个字段精确到小数点后一位，需要使用的是算术函数里的ROUND函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL：SELECT name, ROUND(attack_growth,1) FROM heros</span></span></code></pre></div><p>代码中， <code>ROUND(attack_growth,1)</code> 中的 <code>attack_growth</code> 代表想要处理的数据，“1”代表四舍五入的位数，也就是我们这里需要精确到的位数。</p><p>运行结果为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/fb55a715543e1ed3245ae37210ad75ed.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/fb55a715543e1ed3245ae37210ad75ed.png" alt=""></a></p><p>假设我们想显示英雄最大生命值的最大值，就需要用到MAX函数。在数据中，“最大生命值”对应的列数为 <code>hp_max</code>，在代码中的格式为 <code>MAX(hp_max)</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL：SELECT MAX(hp_max) FROM heros</span></span></code></pre></div><p>运行结果为9328。</p><p>假如我们想要知道最大生命值最大的是哪个英雄，以及对应的数值，就需要分成两个步骤来处理：首先找到英雄的最大生命值的最大值，即 <code>SELECT MAX(hp_max) FROM heros</code>，然后再筛选最大生命值等于这个最大值的英雄，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL：SELECT name, hp_max FROM heros WHERE hp_max = (SELECT MAX(hp_max) FROM heros)</span></span></code></pre></div><p>运行结果：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/9371fdcee4d1f7bdfdd71bc0a58aac20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/9371fdcee4d1f7bdfdd71bc0a58aac20.png" alt=""></a></p><p>假如我们想显示英雄的名字，以及他们的名字字数，需要用到 <code>CHAR_LENGTH</code> 函数。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL：SELECT CHAR_LENGTH(name), name FROM heros</span></span></code></pre></div><p>运行结果为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/415aa09e2fdc121861e3c96bd8a2af8c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/415aa09e2fdc121861e3c96bd8a2af8c.png" alt=""></a></p><p>假如想要提取英雄上线日期（对应字段birthdate）的年份，只显示有上线日期的英雄即可（有些英雄没有上线日期的数据，不需要显示），这里我们需要使用EXTRACT函数，提取某一个时间元素。所以我们需要筛选上线日期不为空的英雄，即 <code>WHERE birthdate is not null</code>，然后再显示他们的名字和上线日期的年份，即：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL： SELECT name, EXTRACT(YEAR FROM birthdate) AS birthdate FROM heros WHERE birthdate is NOT NULL</span></span></code></pre></div><p>或者使用如下形式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL: SELECT name, YEAR(birthdate) AS birthdate FROM heros WHERE birthdate is NOT NULL</span></span></code></pre></div><p>运行结果为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/26cacf4d619d9f177a1f5b22059f9916.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/26cacf4d619d9f177a1f5b22059f9916.png" alt=""></a></p><p>假设我们需要找出在2016年10月1日之后上线的所有英雄。这里我们可以采用DATE函数来判断birthdate的日期是否大于2016-10-01，即 <code>WHERE DATE(birthdate)&gt;&#39;2016-10-01&#39;</code>，然后再显示符合要求的全部字段信息，即：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL： SELECT * FROM heros WHERE DATE(birthdate)&amp;gt;&#39;2016-10-01&#39;</span></span></code></pre></div><p>需要注意的是下面这种写法是不安全的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SELECT * FROM heros WHERE birthdate&amp;gt;&#39;2016-10-01&#39;</span></span></code></pre></div><p>因为很多时候你无法确认birthdate的数据类型是字符串，还是datetime类型，如果你想对日期部分进行比较，那么使用 <code>DATE(birthdate)</code> 来进行比较是更安全的。</p><p>运行结果为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/e5696b5ff0aae0fd910463b1f8e6ed22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/e5696b5ff0aae0fd910463b1f8e6ed22.png" alt=""></a></p><p>假设我们需要知道在2016年10月1日之后上线英雄的平均最大生命值、平均最大法力和最高物攻最大值。同样我们需要先筛选日期条件，即 <code>WHERE DATE(birthdate)&gt;&#39;2016-10-01&#39;</code>，然后再选择 <code>AVG(hp_max), AVG(mp_max), MAX(attack_max)</code> 字段进行显示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SQL： SELECT AVG(hp_max), AVG(mp_max), MAX(attack_max) FROM heros WHERE DATE(birthdate)&amp;gt;&#39;2016-10-01&#39;</span></span></code></pre></div><p>运行结果为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/8f559dc1be7d62e4c58402ebe2e7856b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/8f559dc1be7d62e4c58402ebe2e7856b.png" alt=""></a></p><h2 id="为什么使用sql函数会带来问题" tabindex="-1">为什么使用SQL函数会带来问题 <a class="header-anchor" href="#为什么使用sql函数会带来问题" aria-label="Permalink to &quot;为什么使用SQL函数会带来问题&quot;">​</a></h2><p>尽管SQL函数使用起来会很方便，但我们使用的时候还是要谨慎，因为你使用的函数很可能在运行环境中无法工作，这是为什么呢？</p><p>如果你学习过编程语言，就会知道语言是有不同版本的，比如Python会有2.7版本和3.x版本，不过它们之间的函数差异不大，也就在10%左右。但我们在使用SQL语言的时候，不是直接和这门语言打交道，而是通过它使用不同的数据库软件，即DBMS。DBMS之间的差异性很大，远大于同一个语言不同版本之间的差异。实际上，只有很少的函数是被DBMS同时支持的。比如，大多数DBMS使用（||）或者（+）来做拼接符，而在MySQL中的字符串拼接函数为 <code>Concat()</code>。大部分DBMS会有自己特定的函数，这就意味着采用SQL函数的代码可移植性是很差的，因此在使用函数的时候需要特别注意。</p><h2 id="关于大小写的规范" tabindex="-1">关于大小写的规范 <a class="header-anchor" href="#关于大小写的规范" aria-label="Permalink to &quot;关于大小写的规范&quot;">​</a></h2><p>细心的人可能会发现，我在写SELECT语句的时候用的是大写，而你在网上很多地方，包括你自己写的时候可能用的是小写。实际上在SQL中，关键字和函数名是不用区分字母大小写的，比如SELECT、WHERE、ORDER、GROUP BY等关键字，以及ABS、MOD、ROUND、MAX等函数名。</p><p>不过在SQL中，你还是要确定大小写的规范，因为在Linux和Windows环境下，你可能会遇到不同的大小写问题。</p><p>比如MySQL在Linux的环境下，数据库名、表名、变量名是严格区分大小写的，而字段名是忽略大小写的。</p><p>而MySQL在Windows的环境下全部不区分大小写。</p><p>这就意味着如果你的变量名命名规范没有统一，就可能产生错误。这里有一个有关命名规范的建议：</p><ol><li>关键字和函数名称全部大写；</li><li>数据库名、表名、字段名称全部小写；</li><li>SQL语句必须以分号结尾。</li></ol><p>虽然关键字和函数名称在SQL中不区分大小写，也就是如果小写的话同样可以执行，但是数据库名、表名和字段名在Linux MySQL环境下是区分大小写的，因此建议你统一这些字段的命名规则，比如全部采用小写的方式。同时将关键词和函数名称全部大写，以便于区分数据库名、表名、字段名。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>函数对于一门语言的重要性毋庸置疑，我们在写Python代码的时候，会自己编写函数，也会使用Python内置的函数。在SQL中，使用函数的时候需要格外留意。不过如果工程量不大，使用的是同一个DBMS的话，还是可以使用函数简化操作的，这样也能提高代码效率。只是在系统集成，或者在多个DBMS同时存在的情况下，使用函数的时候就需要慎重一些。</p><p>比如 <code>CONCAT()</code> 是字符串拼接函数，在MySQL和Oracle中都有这个函数，但是在这两个DBMS中作用却不一样， <code>CONCAT</code> 函数在MySQL中可以连接多个字符串，而在Oracle中 <code>CONCAT</code> 函数只能连接两个字符串，如果要连接多个字符串就需要用（||）连字符来解决。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/8c5e316b466e8fa65789a9c6a220ebc9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SQL%E5%BF%85%E7%9F%A5%E5%BF%85%E4%BC%9A/images/103349/8c5e316b466e8fa65789a9c6a220ebc9.jpg" alt=""></a></p><p>讲完了SQL函数的使用，我们来做一道练习题。还是根据王者荣耀英雄数据表，请你使用SQL函数作如下的练习：计算英雄的最大生命平均值；显示出所有在2017年之前上线的英雄，如果英雄没有统计上线日期则不显示。</p><p>欢迎你在评论区与我分享你的答案，也欢迎点击”请朋友读“，把这篇文章分享给你的朋友或者同事。</p>',103)])])}const E=a(n,[["render",p]]);export{b as __pageData,E as default};
